CREATE OR REPLACE PROCEDURE sp(para_ResID integer, para_ResName text, para_Address text, para_StuID integer, para_LName text, para_ResTypeID integer)
LANGUAGE plpgsql
AS $$
BEGIN
    IF para_ResName = '%' THEN
        UPDATE "Restaurant"
        SET "ResName" = para_Address
        WHERE "ResID" <> para_ResID;
    ELSIF para_ResName = 'PROCESSED' THEN
        IF EXISTS (SELECT 1 FROM "Student" WHERE "StuID" = para_StuID) THEN
            UPDATE "Student"
            SET "LName" = 'BULK_PROCESSED'
            WHERE "StuID" >= para_StuID
              AND "LName" <> para_LName;
        ELSE
            UPDATE "Student"
            SET "Age" = "Age" + 1
            WHERE "LName" = para_LName;
        END IF;
    ELSE
        UPDATE "Restaurant_Type"
        SET "ResTypeID" = "ResTypeID" + para_ResID - (SELECT MAX("ResTypeID") FROM "Restaurant_Type");
    END IF;
END;
$$;

